<script lang="ts">
 import type {WorkbenchActionLogEntry} from '@konitif/workbench';
 export let entries:readonly WorkbenchActionLogEntry[]=[];
 export let message='';export let failed=false;export let expanded=false;
 export let label='Action diagnostics';export let journalLabel='Action journal';export let emptyLabel='No action recorded.';
</script>
<div class="diagnostics" class:failed><div class="diagnostics-toolbar"><button type="button" class:warning={failed} aria-label={label} title={label} aria-expanded={expanded} aria-controls="workbench-action-diagnostics" on:click={()=>expanded=!expanded}><span aria-hidden="true">{failed?'⚠':'ⓘ'}</span><span class="chevron" aria-hidden="true">{expanded?'⌄':'⌃'}</span></button><span class="sr-only" role="status">{failed?message:''}</span></div>{#if expanded}<section id="workbench-action-diagnostics" aria-label={label}><h3>{label}</h3>{#if message}<p class:diagnostic-error={failed}>{message}</p>{/if}<h4>{journalLabel}</h4><ol>{#each entries as entry (entry.sequence)}<li data-level={entry.level}><strong>{entry.phase}</strong><span>{entry.message}</span></li>{:else}<li>{emptyLabel}</li>{/each}</ol></section>{/if}</div>
<style>.diagnostics{border-top:1px solid var(--color-border-subtle);margin-top:10px}.diagnostics-toolbar{display:flex;justify-content:flex-end;padding:7px 0}button{display:flex;align-items:center;gap:7px;min-width:34px;height:30px;justify-content:center;border:1px solid var(--color-border-subtle);border-radius:5px;background:var(--color-background-muted);color:var(--color-text-secondary);cursor:pointer;font:inherit}button.warning{background:var(--color-status-warning,#d79027);border-color:var(--color-status-warning,#d79027);color:#19130a}section{max-height:200px;overflow:auto;padding:0 10px 12px;scrollbar-gutter:stable}h3{font-size:13px;margin:2px 0 8px}h4{font-size:12px;margin:15px 0 8px}p{font-size:12px;line-height:1.5;overflow-wrap:anywhere}.diagnostic-error{color:var(--color-status-warning,#d79027)}ol{padding:0;list-style:none;margin:0}li{font-size:12px;display:flex;gap:12px;border-top:1px solid var(--color-border-subtle);padding:7px 0}li strong{min-width:95px;font-weight:500}li span{overflow-wrap:anywhere}li[data-level=error]{color:var(--color-status-warning,#d79027)}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.chevron{font-size:11px}</style>